package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;

/** Share arrangements of live reports, never the owner's data visibility or retained captures. */
final class Dashboards {
 static final List<String> METRICS=List.of("count","value_count","sum","min","max","average");
 private Dashboards() {}
 static void viewer(Store.Db db){if(!Set.of("admin","agent","reader").contains(db.viewerRole))throw new Failure(403,"Reporting access is required");}
 static void author(Store.Db db){if(!Set.of("admin","agent").contains(db.viewerRole))throw new Failure(403,"Staff access is required to manage dashboards");}
 static String visibility(){return "(d.owner_id=? OR d.visibility='workspace' OR (d.visibility='groups' AND EXISTS(SELECT 1 FROM os_dashboard_group g JOIN os_group_member m ON m.group_id=g.group_id JOIN os_record r ON r.sys_id=g.group_id AND r.\"table\"='sys_user_group' WHERE g.dashboard_id=d.dashboard_id AND m.user_id=?)))";}
 static List<Map<String,Object>> list(Store.Db db)throws SQLException {viewer(db);return db.all("SELECT d.dashboard_id,d.name,d.owner_id,d.visibility,d.revision FROM os_dashboard d WHERE "+visibility()+" ORDER BY d.name,d.dashboard_id LIMIT 200",db.viewerId,db.viewerId);}
 static Map<String,Object> find(Store.Db db,String id,boolean owned)throws SQLException {viewer(db);var row=db.one("SELECT d.* FROM os_dashboard d WHERE d.dashboard_id=? AND "+visibility(),id,db.viewerId,db.viewerId);if(row==null || (owned && !row.get("owner_id").equals(db.viewerId)))throw new Failure(404,"Dashboard not found");return row;}
 static Map<String,Object> measure(Store.Db db,String report)throws SQLException {var definition=SavedReports.find(db,db.viewerId,report);require(Objects.toString(object(definition.get("definition")).getOrDefault("group_by",""),"").isEmpty(),"Dashboard metrics require ungrouped numeric reports");var result=SavedReports.run(db,db.viewerId,report);return map("report_id",report,"name",definition.get("name"),"values",objects(result.get("rows")).getFirst());}
 static Map<String,Object> show(Store.Db db,String id)throws SQLException {
  var row=find(db,id,false);var tiles=new ArrayList<Map<String,Object>>();for(var widget:objects(object(row.get("definition")).get("widgets"))){try{var metric=measure(db,widget.get("report_id").toString());tiles.add(map("available",true,"report_id",metric.get("report_id"),"name",metric.get("name"),"metric",widget.get("metric"),"value",object(metric.get("values")).get(widget.get("metric"))));}catch(Failure unavailable){tiles.add(map("available",false,"name","Report unavailable"));}}
  return map("dashboard_id",id,"name",row.get("name"),"visibility",row.get("visibility"),"revision",row.get("revision"),"can_manage",row.get("owner_id").equals(db.viewerId) && Set.of("admin","agent").contains(db.viewerRole),"widgets",tiles);
 }
 static Map<String,Object> editor(Store.Db db,String id)throws SQLException {
  author(db);var row=id.isEmpty()?map("dashboard_id","","name","","visibility","private","revision",0,"definition",map("widgets",List.of())):find(db,id,true);var groups=db.all("SELECT group_id FROM os_dashboard_group WHERE dashboard_id=? ORDER BY group_id",id);var selected=groups.stream().map(g->g.get("group_id")).toList();var widgets=objects(object(row.get("definition")).get("widgets"));var slots=new ArrayList<Map<String,Object>>();for(int n=0;n<8;n++)slots.add(n<widgets.size()?widgets.get(n):map("report_id","","metric","count"));return map("dashboard",row,"slots",slots,"selected_groups",selected,"reports",SavedReports.list(db,db.viewerId),"groups",Service.page(db,"sys_user_group",Map.of("sysparm_limit","100"),"").rows(),"metrics",METRICS);
 }
 static Map<String,Object> save(Store.Db db,String id,Object input)throws SQLException {
  author(db);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var body=object(input);require(body.keySet().equals(Set.of("revision","name","visibility","groups","widgets")),"Provide revision, name, visibility, groups and widgets");require(body.get("revision") instanceof Integer && ((Integer)body.get("revision"))>=0,"Provide a nonnegative integer revision");String name=WorkJobs.text(body.get("name"),160).strip(),visibility=WorkJobs.text(body.get("visibility"),20);require(Set.of("private","workspace","groups").contains(visibility),"Choose private, workspace or groups visibility");require(body.get("groups") instanceof List<?>,"Groups must be a list");var groups=(List<?>)body.get("groups");require(visibility.equals("groups")?groups.size()>=1 && groups.size()<=5:groups.isEmpty(),"Select 1 to 5 teams only for groups visibility");require(new HashSet<>(groups).size()==groups.size(),"Use distinct teams");for(var group:groups){require(group instanceof String && ((String)group).matches("[0-9a-f]{32}"),"Use existing team IDs");Service.readRecord(db,"sys_user_group",group.toString());}
  require(body.get("widgets") instanceof List<?>,"Widgets must be a list");var widgets=(List<?>)body.get("widgets");require(!widgets.isEmpty() && widgets.size()<=8,"Provide 1 to 8 ordered metrics");var seen=new HashSet<String>();for(var value:widgets){var widget=object(value);require(widget.keySet().equals(Set.of("report_id","metric")),"Provide report_id and metric per widget");String report=WorkJobs.text(widget.get("report_id"),32),metric=WorkJobs.text(widget.get("metric"),20);require(report.matches("[0-9a-f]{32}") && METRICS.contains(metric),"Choose an existing report and supported metric");require(seen.add(report+":"+metric),"Do not repeat the same report metric");measure(db,report);}
  int revision=0;if(!id.isEmpty())revision=((Number)find(db,id,true).get("revision")).intValue();if(!body.get("revision").equals(revision))throw new Failure(409,"Dashboard changed; reload before saving");if(id.isEmpty()){require(db.count("SELECT COUNT(*) FROM os_dashboard WHERE owner_id=?",db.viewerId)<50,"Owned dashboard limit reached");id=id();db.update("INSERT INTO os_dashboard(dashboard_id,owner_id,name,visibility,revision,definition) VALUES(?,?,'','private',0,?)",id,db.viewerId,JSON.writeValueAsString(map("widgets",List.of())));}
  db.update("UPDATE os_dashboard SET name=?,visibility=?,revision=?,definition=? WHERE dashboard_id=?",name,visibility,revision+1,JSON.writeValueAsString(map("widgets",widgets)),id);db.update("DELETE FROM os_dashboard_group WHERE dashboard_id=?",id);for(var group:groups)db.update("INSERT INTO os_dashboard_group(dashboard_id,group_id) VALUES(?,?)",id,group);SecurityEvents.record(db,db.viewerId,db.viewerId,"dashboard.saved",map("dashboard_id",id,"revision",revision+1,"visibility",visibility));return show(db,id);
 }
 static void remove(Store.Db db,String id,Object input)throws SQLException {author(db);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var row=find(db,id,true);var body=object(input);require(body.keySet().equals(Set.of("revision")) && body.get("revision") instanceof Integer,"Provide integer revision only");if(!row.get("revision").toString().equals(body.get("revision").toString()))throw new Failure(409,"Dashboard changed; reload before deleting");db.update("DELETE FROM os_dashboard_group WHERE dashboard_id=?",id);db.update("DELETE FROM os_dashboard WHERE dashboard_id=?",id);SecurityEvents.record(db,db.viewerId,db.viewerId,"dashboard.deleted",map("dashboard_id",id));}
 static Map<String,Object> form(Map<String,String> form){var body=new LinkedHashMap<String,Object>(form);body.remove("csrf");body.put("revision",Service.number(Objects.toString(body.get("revision"),""),0,Integer.MAX_VALUE));var groups=new ArrayList<String>();for(int n=1;n<=5;n++){String group=Objects.toString(body.remove("group_"+n),"");if(!group.isEmpty())groups.add(group);}var widgets=new ArrayList<Map<String,Object>>();for(int n=1;n<=8;n++){String report=Objects.toString(body.remove("report_"+n),""),metric=Objects.toString(body.remove("metric_"+n),"");if(!report.isEmpty())widgets.add(map("report_id",report,"metric",metric));}body.put("groups",groups);body.put("widgets",widgets);return body;}
}
